import React, { useState, useEffect } from "react";
import { startLiveBot } from "../services/api";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const LiveMeetingBot = () => {
  const [link, setLink] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [botJoined, setBotJoined] = useState(false);

  const navigate = useNavigate();

  // 🔹 Listen for meeting end event (sent by extension / recorder)
  useEffect(() => {
    const handleMeetingEnd = async (event) => {
      try {
        const audioBlob = event.detail.audio; // recorded system audio

        const formData = new FormData();
        formData.append("audio", audioBlob, "meeting.webm");

        const res = await axios.post(
          "http://localhost:5000/api/livebot/end",
          formData,
          {
            headers: { "Content-Type": "multipart/form-data" },
          }
        );

        // 🔹 Navigate to result page with AI analysis
        navigate("/result", { state: res.data.analysis });

      } catch (err) {
        console.error("Meeting processing failed:", err);
        setError("Failed to analyze meeting");
      }
    };

    window.addEventListener("meeting-ended", handleMeetingEnd);

    return () => {
      window.removeEventListener("meeting-ended", handleMeetingEnd);
    };
  }, [navigate]);

  // 🔹 Start live meeting bot
  const handleStartBot = async () => {
    if (!link.trim()) {
      setError("Please enter a meeting link");
      return;
    }

    setLoading(true);
    setError(null);
    setBotJoined(false);

    try {
      await startLiveBot({ meetingLink: link });

      setBotJoined(true);
      setLink("");

      // 🔹 Tell extension to start recording system audio
      window.postMessage({ type: "START_RECORDING" }, "*");

    } catch (err) {
      setError(err.response?.data?.error || "Failed to start bot");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card">
      <h2>Live Meeting Bot</h2>

      <input
        type="text"
        placeholder="Enter Google Meet / Zoom link"
        value={link}
        onChange={(e) => setLink(e.target.value)}
        disabled={botJoined}
        style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
      />

      {error && <p style={{ color: "red" }}>{error}</p>}

      {botJoined && (
        <p style={{ color: "green", fontWeight: "bold" }}>
          🤖 Bot joined successfully. Recording in progress...
        </p>
      )}

      {!botJoined && (
        <button onClick={handleStartBot} disabled={loading}>
          {loading ? "Joining..." : "Join Meeting"}
        </button>
      )}
    </div>
  );
};

export default LiveMeetingBot;
